const float PI = 3.14159;

vec3 hsv(float h, float s, float v){
    vec4 t = vec4(2.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(vec3(h) + t.xyz) * 06.0 - vec3(t.w));
    return v * mix(vec3(t.x), clamp(p - vec3(t.x), 0.0, 1.0), s);
}

mat3 setCamera(vec3 ro, vec3 tg, float cr){
vec3 cw = normalize(tg-ro);
vec3 cu = normalize(cross(cw,vec3(sin(cr), cos(cr), 0.0)));
vec3 cv = cross(cu,cw);
    return mat3(cu, cv, cw);
}

mat2 rotate2D(float r){
    float c = cos(r);
    float s = sin(r);
    return mat2(c, s, -s, c);
}
#define Q(p) p *= 2.*r(round(atan(p.x, p.y) * 4.) / 4.)
#define r(a) mat2(cos(a + asin(vec4(0,1,-1,0))))
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = 2.0 * (fragCoord.xy - 0.5 * iResolution.xy) / min(iResolution.y, iResolution.x);

    vec3 r = normalize(vec3(uv, 1.0 - dot(uv, uv) *1.3));
    vec3 col = vec3(0);

    float t = iTime;

    vec3 ro = vec3(0., 0, -1);
    ro.zx*=rotate2D(iTime);
        ro.yx*=rotate2D(iTime);
            ro.zy*=rotate2D(iTime);
    vec3 tg = vec3(0);

    mat3 ca = setCamera(ro, tg, 0.);
    vec3 rd = ca * normalize(vec3(uv, 1.));

    vec3 p,q;
    float td=.1, d;
  Q(p.xy);
    for(int i=0;i<40;++i){
        p = ro + td * rd;
       Q(p.xy);
        for(int i=0;i<4;++i){
            p=abs(p)-.3;
            p.yz*=rotate2D(PI*.5);
            p.xz*=rotate2D(PI*.25);
        }
        q=mod(abs(p+r-.5),1.)-.5;

        d = abs(length(vec2(length(q.xz) - 1., q.y)) - .9);



        if(d < 0.001){
            col += hsv(sin(q.x*q.y*8.+t), .8, .02/abs(sin(atan(q.x, q.z)*2.+t)*sin(atan(q.y, q.z)*2.+t)+.1));
            d+=0.003;
        }
        td += d;
    }
    fragColor = vec4(col,1.0);
}
